1: import {
2:   Transaction,
3:   CreateTransactionRequest,
4:   UpdateTransactionRequest,
5:   TransactionResponse,
6:   TransactionsListResponse,
7: } from "@/types/transactions";
8: import { fetchApi } from "@/utils/apiClient";
9: 
10: export async function getTransaction(id: string): Promise<Transaction> {
11:   try {
12:     const response = await fetchApi(`/account/transaction/${id}`, {
13:       method: "GET",
14:     });
15: 
16:     if (!response.ok) {
17:       const errorText = await response.text().catch(() => response.statusText);
18:       throw new Error(`Erro ao buscar transação: ${response.status} ${errorText}`);
19:     }
20: 
21:     const result: TransactionsListResponse | TransactionResponse = await response.json();
22: 
23:     if (!result || !result.result) {
24:       throw new Error("Resposta inválida do servidor");
25:     }
26: 
27:     if (typeof result.result === "object" && !Array.isArray(result.result)) {
28:       const transaction = result.result as Transaction;
29:       if (transaction.id || transaction.accountId) {
30:         return transaction;
31:       }
32:     }
33: 
34:     if (Array.isArray(result.result)) {
35:       if (result.result.length === 0) {
36:         throw new Error("Transação não encontrada");
37:       }
38:       return result.result[0];
39:     }
40: 
41:     if (result.result && typeof result.result === "object" && "transactions" in result.result) {
42:       const transactions = (result.result as { transactions: Transaction[] }).transactions;
43:       if (transactions.length === 0) {
44:         throw new Error("Transação não encontrada");
45:       }
46:       return transactions[0];
47:     }
48: 
49:     throw new Error("Formato de resposta inválido do servidor");
50:   } catch (error) {
51:     if (error instanceof Error) {
52:       throw error;
53:     }
54:     throw new Error("Erro ao buscar transação");
55:   }
56: }
57: 
58: export async function createTransaction(data: CreateTransactionRequest): Promise<Transaction> {
59:   try {
60:     const response = await fetchApi("/account/transaction", {
61:       method: "POST",
62:       body: JSON.stringify(data),
63:     });
64: 
65:     const result: TransactionResponse = await response.json();
66:     return result.result;
67:   } catch (error) {
68:     throw new Error(error instanceof Error ? error.message : "Erro ao criar transação");
69:   }
70: }
71: 
72: export async function updateTransaction(
73:   id: string,
74:   data: UpdateTransactionRequest
75: ): Promise<Transaction> {
76:   try {
77:     const response = await fetchApi(`/account/transaction/${id}`, {
78:       method: "PUT",
79:       body: JSON.stringify(data),
80:     });
81: 
82:     const result: TransactionResponse = await response.json();
83:     return result.result;
84:   } catch (error) {
85:     throw new Error(error instanceof Error ? error.message : "Erro ao atualizar transação");
86:   }
87: }
88: 
89: export async function deleteTransaction(id: string): Promise<void> {
90:   try {
91:     await fetchApi(`/account/transaction/${id}`, {
92:       method: "DELETE",
93:     });
94:   } catch (error) {
95:     throw new Error(error instanceof Error ? error.message : "Erro ao excluir transação");
96:   }
97: }

