13: export async function fetchApi(
14:   url: string,
15:   options: RequestInit = {}
16: ): Promise<Response> {
17:   const token = getAuthToken();
18:   const headers: HeadersInit = {
19:     "Content-Type": "application/json",
20:     ...options.headers,
21:   };
22: 
23:   if (token) {
24:     headers["Authorization"] = `Bearer ${token}`;
25:   }
26: 
27:   const API_BASE_URL = getApiBaseUrl();
28: 
29:   try {
30:     const response = await fetch(`${API_BASE_URL}${url}`, {
31:       ...options,
32:       headers,
33:     });
34: 
35:     if (!response.ok) {
36:       if (response.status === 401) {
37:         removeLocalStorageItem(STORAGE_KEYS.TOKEN);
38:         if (isWindowAvailable()) {
39:           window.location.href = ROUTES.AUTH;
40:         }
41:         const errorText = await response
42:           .text()
43:           .catch(() => response.statusText);
44:         throw new Error(`Erro na requisição: ${response.status} ${errorText}`);
45:       }
46:       const errorText = await response.text().catch(() => response.statusText);
47:       throw new Error(`Erro na requisição: ${response.status} ${errorText}`);
48:     }
49: 
50:     return response;
51:   } catch (error) {
52:     if (error instanceof TypeError && error.message.includes("fetch")) {
53:       throw new Error(
54:         "Erro de conexão: Não foi possível conectar ao servidor. Verifique se o backend está rodando."
55:       );
56:     }
57:     if (error instanceof Error && error.message.includes("CORS")) {
58:       throw new Error(
59:         "Erro de CORS: O servidor não permite requisições desta origem."
60:       );
61:     }
62:     throw error;
63:   }
64: }

